/// The "product_tags" table, as the database has it. Fluent never creates or changes it: the database already exists.
final class ProductTagModel: Model, @unchecked Sendable {
    static let schema = "product_tags"

    /// The key, a value of each of its columns.
    final class IDValue: Fields, Hashable, @unchecked Sendable {
        @Field(key: "product_id")
        var productId: Int

        @Field(key: "tag_id")
        var tagId: Int

        init() {}

        static func == (lhs: IDValue, rhs: IDValue) -> Bool {
            lhs.productId == rhs.productId && lhs.tagId == rhs.tagId
        }

        func hash(into hasher: inout Hasher) {
            hasher.combine(productId)
            hasher.combine(tagId)
        }
    }

    @CompositeID()
    var id: IDValue?

    init() {}
}

